.funnel-page{width:100%;max-width:100rem;margin:0 auto}.funnel-header{display:flex;align-items:flex-end;justify-content:space-between;gap:1rem;margin-bottom:1rem}.funnel-header h1,.funnel-header p{margin:.15rem 0}.funnel-actions{display:flex;flex-wrap:wrap;gap:.55rem}.funnel-filter{display:grid!important;grid-template-columns:.55fr repeat(4,minmax(11rem,1fr)) auto auto;gap:.65rem;align-items:end;max-width:none!important;margin:0 0 1rem;padding:1rem;border:1px solid #dbe3e8;border-radius:1rem;background:#fff}.funnel-filter label{margin:0}.funnel-filter input,.funnel-filter select,.funnel-filter button,.funnel-filter a{min-height:3rem;margin:0}.funnel-flow{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:.65rem;margin-bottom:1rem}.funnel-step{position:relative;display:grid;gap:.25rem;min-width:0;padding:1rem;border:1px solid #dbe3e8;border-radius:.95rem;background:#fff;box-shadow:0 .35rem 1rem rgb(23 33 43 / 5%)}.funnel-step:not(:last-child)::after{content:'›';position:absolute;top:50%;right:-.56rem;z-index:2;display:grid;place-items:center;width:1.1rem;height:1.1rem;border-radius:50%;color:#fff;background:var(--inter-accent);font-weight:900;transform:translateY(-50%)}.funnel-step i{color:var(--inter-accent)}.funnel-step span{color:var(--inter-muted);font-size:.78rem}.funnel-step strong{font-size:1.45rem}.funnel-step small{min-height:1rem;color:#506878}.funnel-note{display:flex;align-items:flex-start;gap:.6rem;margin:-.2rem 0 1rem;padding:.8rem 1rem;border-radius:.8rem;color:#4a6272;background:#eef4f7}.funnel-note p{margin:0}.funnel-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1rem;margin-bottom:1rem}.funnel-card{min-width:0;overflow:hidden;border:1px solid #dbe3e8;border-radius:1rem;background:#fff}.funnel-card.wide{grid-column:1/-1}.funnel-card header{display:flex;align-items:flex-start;justify-content:space-between;gap:1rem;padding:1rem 1.1rem;border-bottom:1px solid #e2e7eb}.funnel-card h2,.funnel-card p{margin:.1rem 0}.funnel-