 <div class="funnel-grid">
  <section class="funnel-card"><header><div><h2>Origem dos resultados</h2><p class="meta">Canais que trouxeram Leads e vendas.</p></div><i class="fa-solid fa-bullhorn"></i></header><?php if($funnel['channels']===[]):?><div class="funnel-empty"><i class="fa-solid fa-chart-simple"></i><strong>Ainda não há canais identificados.</strong></div><?php else:?><div class="table-responsive"><table><thead><tr><th>Origem</th><th>Leads</th><th>Pedidos</th><th>Pagos</th></tr></thead><tbody><?php foreach($funnel['channels']as$row):?><tr><td><strong><?= $escape($row['label']) ?></strong></td><td><?= $number((int)$row['leads']) ?></td><td><?= $number((int)$row['orders']) ?></td><td><?= $number((int)$row['paid']) ?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
  <section class="funnel-card"><header><div><h2>Desempenho por curso</h2><p class="meta">Cursos que mais avançaram no funil.</p></div><i class="fa-solid fa-book-open"></i></header><?php if($funnel['courses']===[]):?><div class="funnel-empty"><i class="fa-solid fa-book"></i><strong>Nenhum pedido no período.</strong></div><?php else:?><div class="table-responsive"><table><thead><tr><th>Curso</th><th>Pedidos</th><th>Pagos</th><th>Receita</th></tr></thead><tbody><?php foreach($funnel['courses']as$row):?><tr><td><strong><?= $escape($row['label']) ?></strong></td><td><?= $number((int)$row['orders']) ?></td><td><?= $number((int)$row['paid']) ?></td><td><?= $money((float)$row['revenue']) ?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
