  <section class="funnel-card" id="recuperacao"><header><div><h2>Recuperação de oportunidades</h2><p class="meta">Alertas automáticos em 30 minutos, 24 horas e 3 dias.</p></div><div class="recovery-summary"><span class="funnel-badge"><?= $number($summary['recovery']) ?> pendente(s)</span><span class="funnel-badge success"><?= $number($summary['recovered']) ?> recuperada(s) · <?= $money($summary['recovered_amount']) ?></span></div></header><?php if($funnel['recovery']===[]):?><div class="funnel-empty"><i class="fa-solid fa-circle-check"></i><strong>Nenhuma oportunidade pendente.</strong><span>Ótimo: não há checkout antigo aguardando retorno.</span></div><?php else:?><div class="table-responsive"><table><thead><tr><th>Interessado</th><th>Curso / polo</th><th>Alerta</th><th>Ações</th></tr></thead><tbody><?php foreach($funnel['recovery']as$row):$phone=preg_replace('/\D/','',(string)($row['contact_phone']??''))??'';if($phone!==''&&!str_starts_with($phone,'55'))$phone='55'.$phone;$name=trim((string)($row['contact_name']??''))?:'Olá';$firstName=explode(' ',$name)[0];$message=rawurlencode('Olá, '.$firstName.'! Vi que você iniciou a inscrição no curso '.$row['product_name'].', mas o pagamento ainda não foi concluído. Posso ajudar?'.(!empty($row['link'])?' Você pode retomar por aqui: '.$row['link']:''));$stage=(int)($row['alert_stage']??1);$stageLabel=$stage>=3?'3 dias':($stage===2?'24 horas':'30 minutos');?><tr><td><span class="recovery-contact"><strong><?= $escape($name) ?></strong><small><?= $escape($row['contact_email']?:'Sem e-mail') ?></small></span></td><td><strong><?= $escape($row['product_name']) ?></strong><br><small><?= $escape($row['unit_name']) ?></small></td><td><span class="recovery-stage"><?= $escape($stageLabel) ?></span></td><td><div class="recovery-actions"><?php if($phone!==''):?><a class="button button-secondary button-icon" href="https://wa.me/<?= $escape($phone) ?>?text=<?= $escape($message) ?>" target="_blank" title="Enviar mensagem pronta no WhatsApp"><i class="fa-brands fa-whatsapp"></i></a><?php endif;?><?php if((int)($row['contact_id']??0)>0):?><a class="button button-secondary button-icon" href="<?= $escape($basePath) ?>/crm/contacts/<?= (int)$row['contact_id'] ?>" title="Abrir Lead e follow-up"><i class="fa-solid fa-user-clock"></i></a><?php endif;?><?php if(!empty($row['link'])):?><a class="button button-secondary button-icon" href="<?= $escape($row['link']) ?>" target="_blank" title="Abrir checkout"><i class="fa-solid fa-arrow-up-right-from-square"></i></a><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
